"""Provisional netlist and footprints for the Dual-NCE motherboard.

PROVISIONAL. Every ball assignment, package outline and phase position here
is a placeholder chosen to be STRUCTURALLY right so that placement and
routing can proceed. None of it is a released pinout. The markers that say
so are deliberate and should stay until a real ball map replaces them:

  * every component carries a "PROVISIONAL" field
  * the BGA ball map is generated by rule, not read from a vendor file
  * net names are architectural, not silicon signal names

What IS taken from the architecture rather than invented:

  blueprint        2 x BGA-2500 compute units, 48 DrMOS phases,
                   TFLN photonic bridge, CVD diamond cooling overlay
  l04_wdm.py       16 WDM channels. 200 Gbps PAM4 per lane is the TARGET
                   rate (3.2T aggregate); the digital framing layer drives
                   33.3 Mbps per lane today. The CHANNEL COUNT is what sets
                   the ball count here, and that is solid either way.
                   See docs/BANDWIDTH-STATEMENT.md.
  nce_tfln_pkg.sv  the die-to-die datapath is OPTICAL; copper carries only
                   the modulator drive and the TIA output to the PIC edge

That last point is why there is no wide copper bus between the dies. The
only high-speed copper is die -> PIC, 16 TX pairs and 16 RX pairs per die.

Run with KiCad's bundled Python:
    ".../KiCad/10.0/bin/python.exe" build_schematic.py
"""

from __future__ import annotations

import os
import sys

import pcbnew

MM = 1_000_000


def mm(x: float) -> int:
    return int(round(x * MM))


# --- geometry, mirrored from build_board.py --------------------------------
BOARD_W_MM, BOARD_H_MM = 420.0, 350.0
DIE_SIZE_MM, DIE_GAP_MM = 55.0, 60.0

# --- BGA-2500 --------------------------------------------------------------
# 50 x 50 = 2500 balls. At 1.1 mm pitch the array spans 53.9 mm, which is the
# 55 mm package in the blueprint with a 0.55 mm keepout at each edge.
BGA_N = 50
BGA_PITCH_MM = 1.1
BALL_DIA_MM = 0.6

# --- optical lanes ---------------------------------------------------------
# 16 WDM channels per direction per die (l04_wdm.py). The lane COUNT is
# what matters for the ball map; the per-lane RATE is a target, not current.
# Differential, so 2 balls per lane.
WDM_LANES = 16

# --- VRM -------------------------------------------------------------------
# The blueprint annotates "48 DrMOS phases for 1000A+ delivery". build_board.py
# placed 24 markers, which was half the phase count.
DRMOS_PHASES = 48
DRMOS_W_MM, DRMOS_H_MM = 6.0, 6.0


def new_footprint(board: pcbnew.BOARD, ref: str, value: str,
                  x: float, y: float, label_dy: float = 0.0) -> pcbnew.FOOTPRINT:
    """Create a footprint and park its reference designator CLEAR of copper.

    A reference field defaults to the component origin, which on a BGA is the
    middle of 2500 balls and on a DrMOS is on top of the switch node. Left
    there it is silkscreen over pads -- the single largest DRC category on
    this board before this was fixed, and a real fab issue rather than a
    cosmetic one: silk printed over an exposed pad is clipped by the solder
    mask and the designator becomes unreadable on the assembled board.
    label_dy lifts it above the package outline instead.
    """
    fp = pcbnew.FOOTPRINT(board)
    fp.SetReference(ref)
    fp.SetValue(value)
    fp.SetPosition(pcbnew.VECTOR2I(mm(x), mm(y)))

    refr = fp.Reference()
    refr.SetPosition(pcbnew.VECTOR2I(mm(x), mm(y + label_dy)))
    refr.SetTextSize(pcbnew.VECTOR2I(mm(1.0), mm(1.0)))
    refr.SetTextThickness(mm(0.15))
    # The value field would land in the same place and collide with the
    # reference; it carries nothing a fab needs on a provisional board.
    fp.Value().SetVisible(False)
    # Mark provisional in the footprint itself, so it travels with the data
    # rather than living only in this file's docstring.
    #
    # On F.Fab, NOT F.Silkscreen. A custom field defaults to visible on the
    # silkscreen layer, which a 3D render of the board made obvious: 51
    # copies of "placeholder - not a released pinout" were printed across
    # the board and would have been plotted into the Gerbers and physically
    # screen-printed. F.Fab is a documentation layer -- it travels with the
    # design, appears in fab drawings, and is not manufactured.
    try:
        fp.SetField("PROVISIONAL", "placeholder - not a released pinout")
        for fld in fp.GetFields():
            if fld.GetName() == "PROVISIONAL":
                fld.SetLayer(pcbnew.F_Fab)
                fld.SetTextSize(pcbnew.VECTOR2I(mm(0.8), mm(0.8)))
    except Exception:
        pass
    board.Add(fp)
    return fp


def add_smd_pad(fp: pcbnew.FOOTPRINT, name: str, ax: float, ay: float,
                w: float, h: float, net: pcbnew.NETINFO_ITEM | None,
                circle: bool = False) -> pcbnew.PAD:
    """Place a pad at ABSOLUTE board coordinates ax, ay in mm.

    Absolute rather than footprint-relative on purpose: fp.GetPosition()
    returns a SwigPyObject with no .x in the KiCad 10 binding, so reading
    the parent's origin back out to offset from it raises AttributeError.
    Every caller already knows the component centre it is placing around,
    so it can do the addition itself and never query the footprint.
    """
    pad = pcbnew.PAD(fp)
    pad.SetNumber(name)
    pad.SetAttribute(pcbnew.PAD_ATTRIB_SMD)
    pad.SetShape(pcbnew.PAD_SHAPE_CIRCLE if circle else pcbnew.PAD_SHAPE_RECT)
    pad.SetSize(pcbnew.VECTOR2I(mm(w), mm(h)))
    pad.SetPosition(pcbnew.VECTOR2I(mm(ax), mm(ay)))
    pad.SetLayerSet(pad.SMDMask())
    if net is not None:
        pad.SetNet(net)
    fp.Add(pad)
    return pad


def ball_name(row: int, col: int) -> str:
    """JEDEC-style row letters, skipping I, O, Q, S, X, Z."""
    alpha = "ABCDEFGHJKLMNPRTUVWY"
    r = ""
    n = row
    while True:
        r = alpha[n % len(alpha)] + r
        n = n // len(alpha) - 1
        if n < 0:
            break
    return "%s%d" % (r, col + 1)


def classify_ball(row: int, col: int, pic_side: str) -> str:
    """Decide what a ball carries. PROVISIONAL, by rule.

    The rule reflects how a high-current compute BGA is actually organised,
    which is what matters for whether the layout is realistic:

      * the two outer rings are signal and are where escape routing starts
      * the interior is a VDD/GND checkerboard, because 1000 A has to come
        up through the ball field and alternating rails keeps loop
        inductance low
      * the rows nearest the PIC are reserved for the optical lane drives,
        since those are the only high-speed copper on the board and they
        must escape toward the bridge
    """
    edge = min(row, col, BGA_N - 1 - row, BGA_N - 1 - col)

    # Optical lanes: two rows on the PIC-facing edge, inset past the outer ring.
    pic_col = BGA_N - 1 if pic_side == "right" else 0
    near_pic = abs(col - pic_col) in (1, 2)
    if near_pic and 4 <= row < 4 + WDM_LANES * 2:
        return "optical"

    if edge < 2:
        return "signal"
    return "vdd" if (row + col) % 2 == 0 else "gnd"


def build_bga(board: pcbnew.BOARD, ref: str, cx: float, cy: float,
              pic_side: str, nets: dict) -> dict:
    fp = new_footprint(board, ref, "NCE-BGA2500", cx, cy,
                       label_dy=-(DIE_SIZE_MM / 2.0 + 2.0))
    span = (BGA_N - 1) * BGA_PITCH_MM
    x0 = -span / 2.0
    y0 = -span / 2.0

    tally = {"vdd": 0, "gnd": 0, "signal": 0, "optical": 0}
    lane_idx = 0
    for row in range(BGA_N):
        for col in range(BGA_N):
            kind = classify_ball(row, col, pic_side)
            if kind == "vdd":
                net = nets["VDD"]
            elif kind == "gnd":
                net = nets["GND"]
            elif kind == "optical":
                # Two balls per differential lane; first half TX, second RX.
                lane = lane_idx // 2
                pol = "P" if lane_idx % 2 == 0 else "N"
                direction = "TX" if lane < WDM_LANES else "RX"
                ln = lane % WDM_LANES
                key = "%s_%s%d_%s" % (ref, direction, ln, pol)
                net = nets.setdefault(key, make_net(board, key))
                lane_idx += 1
            else:
                key = "%s_IO%d_%d" % (ref, row, col)
                net = nets.setdefault(key, make_net(board, key))
            tally[kind] += 1
            add_smd_pad(fp, ball_name(row, col),
                        cx + x0 + col * BGA_PITCH_MM,
                        cy + y0 + row * BGA_PITCH_MM,
                        BALL_DIA_MM, BALL_DIA_MM, net, circle=True)

    # Courtyard, so DRC can police the keepout around a 55 mm package.
    rect = pcbnew.PCB_SHAPE(fp)
    rect.SetShape(pcbnew.SHAPE_T_RECT)
    rect.SetStart(pcbnew.VECTOR2I(mm(cx - DIE_SIZE_MM / 2), mm(cy - DIE_SIZE_MM / 2)))
    rect.SetEnd(pcbnew.VECTOR2I(mm(cx + DIE_SIZE_MM / 2), mm(cy + DIE_SIZE_MM / 2)))
    rect.SetLayer(pcbnew.F_CrtYd)
    rect.SetWidth(mm(0.05))
    fp.Add(rect)
    return tally


def make_net(board: pcbnew.BOARD, name: str) -> pcbnew.NETINFO_ITEM:
    n = board.FindNet(name)
    if n is None:
        n = pcbnew.NETINFO_ITEM(board, name)
        board.Add(n)
    return n


def build_pic(board: pcbnew.BOARD, cx: float, cy: float, nets: dict) -> int:
    """TFLN photonic bridge. Electrical pads only -- the optics are not a
    PCB object. Each die contributes 16 TX and 16 RX differential lanes."""
    pic_w = DIE_GAP_MM - 10.0
    pic_h = DIE_SIZE_MM / 2.0
    fp = new_footprint(board, "PIC1", "TFLN-BRIDGE-3T2", cx, cy,
                       label_dy=-(pic_h / 2.0 + 2.0))

    count = 0
    # Differential pad geometry has to satisfy the clearance rule TWICE: the
    # gap inside a pair, and the gap to the next pair. With lane pitch p,
    # intra-pair spacing s and pad height h, both constraints are
    #     s - h >= clearance        and     (p - s) - h >= clearance
    # which together need p >= 2h + 2*clearance. At p = 0.8 and a 0.20 mm
    # rule that caps h at 0.20. The first attempt used s = 0.35, h = 0.25,
    # giving a 0.10 mm intra-pair gap -- DRC caught it 64 times.
    pitch = 0.8
    pad_h = 0.18
    pair_s = 0.40          # gaps: 0.40-0.18 = 0.22 intra, 0.40-0.18 = 0.22 inter
    for side, ref in (("left", "U1"), ("right", "U2")):
        sx = -pic_w / 2.0 + 0.6 if side == "left" else pic_w / 2.0 - 0.6
        for i in range(WDM_LANES * 2):          # TX and RX
            direction = "TX" if i < WDM_LANES else "RX"
            ln = i % WDM_LANES
            # The PIC's RX pad meets the die's TX net, and vice versa.
            peer = "RX" if direction == "TX" else "TX"
            for pol in ("P", "N"):
                key = "%s_%s%d_%s" % (ref, peer, ln, pol)
                net = nets.setdefault(key, make_net(board, key))
                dy = -(WDM_LANES * 2 * pitch) / 2.0 + i * pitch + \
                     (0.0 if pol == "P" else pair_s)
                add_smd_pad(fp, "%s_%s%d%s" % (ref, direction, ln, pol),
                            cx + sx, cy + dy, 0.3, pad_h, net)
                count += 1

    rect = pcbnew.PCB_SHAPE(fp)
    rect.SetShape(pcbnew.SHAPE_T_RECT)
    rect.SetStart(pcbnew.VECTOR2I(mm(cx - pic_w / 2), mm(cy - pic_h / 2)))
    rect.SetEnd(pcbnew.VECTOR2I(mm(cx + pic_w / 2), mm(cy + pic_h / 2)))
    rect.SetLayer(pcbnew.F_CrtYd)
    rect.SetWidth(mm(0.05))
    fp.Add(rect)
    return count


def build_vrm(board: pcbnew.BOARD, nets: dict) -> int:
    """48 DrMOS phases, two banks of 24, one bank per die."""
    per_bank = DRMOS_PHASES // 2
    rows = 2
    per_row = per_bank // rows
    placed = 0
    for bank, y_base in ((0, 20.0), (1, BOARD_H_MM - 20.0 - DRMOS_H_MM)):
        for r in range(rows):
            y = y_base + r * (DRMOS_H_MM + 2.0) * (1 if bank == 0 else -1)
            span = BOARD_W_MM - 100.0
            step = span / max(per_row - 1, 1)
            for i in range(per_row):
                x = 50.0 + i * step
                idx = bank * per_bank + r * per_row + i
                fp = new_footprint(board, "U%03d" % (100 + idx),
                                   "DrMOS", x, y,
                                   label_dy=-(DRMOS_H_MM / 2.0 + 1.5))
                sw = nets.setdefault("SW%d" % idx,
                                     make_net(board, "SW%d" % idx))
                pwm = nets.setdefault("PWM%d" % idx,
                                      make_net(board, "PWM%d" % idx))
                add_smd_pad(fp, "VIN", x - 2.0, y - 2.0, 2.0, 2.0, nets["VIN"])
                add_smd_pad(fp, "GND", x - 2.0, y + 2.0, 2.0, 2.0, nets["GND"])
                add_smd_pad(fp, "SW",  x + 2.0, y + 0.0, 2.0, 3.0, sw)
                add_smd_pad(fp, "PWM", x + 0.0, y - 2.5, 0.8, 0.8, pwm)
                add_smd_pad(fp, "VCC", x + 0.0, y + 2.5, 0.8, 0.8, nets["VDD"])
                rect = pcbnew.PCB_SHAPE(fp)
                rect.SetShape(pcbnew.SHAPE_T_RECT)
                rect.SetStart(pcbnew.VECTOR2I(mm(x - DRMOS_W_MM / 2),
                                              mm(y - DRMOS_H_MM / 2)))
                rect.SetEnd(pcbnew.VECTOR2I(mm(x + DRMOS_W_MM / 2),
                                            mm(y + DRMOS_H_MM / 2)))
                rect.SetLayer(pcbnew.F_CrtYd)
                rect.SetWidth(mm(0.05))
                fp.Add(rect)
                placed += 1
    return placed


def main() -> int:
    here = os.path.dirname(os.path.abspath(__file__))
    path = os.path.join(here, "lightrail_dual_nce.kicad_pcb")
    board = pcbnew.LoadBoard(path)

    # Drop any previous provisional components so this is idempotent.
    for fp in list(board.GetFootprints()):
        board.Remove(fp)

    # build_board.py drew silkscreen rectangles and labels to MARK where the
    # dies and VRM phases would go. Real footprints now occupy those places,
    # so the markers are duplicate artwork sitting on top of copper -- 294
    # silk violations between them. Placeholders are deleted once the thing
    # they stood for exists.
    # The placeholder silkscreen is NOT deleted here. Three different routes
    # into the KiCad 10 drawings container failed, each differently:
    # GetDrawings() calls list() on a non-iterable SwigPyObject; iterating
    # Drawings() raises TypeError despite advertising __iter__; and index
    # access works on a freshly loaded board but loses len() once footprints
    # have been removed. Rather than keep guessing at a binding that changes
    # behaviour depending on what was touched before it, build_board.py now
    # takes --no-markers and simply never draws them. Deleting artwork is a
    # worse idea than not creating it.

    nets = {"GND": make_net(board, "GND"),
            "VDD": make_net(board, "VDD"),
            "VIN": make_net(board, "VIN")}

    cy = BOARD_H_MM / 2.0
    cx = BOARD_W_MM / 2.0
    left_x = cx - DIE_GAP_MM / 2.0 - DIE_SIZE_MM / 2.0
    right_x = cx + DIE_GAP_MM / 2.0 + DIE_SIZE_MM / 2.0

    t1 = build_bga(board, "U1", left_x, cy, "right", nets)
    t2 = build_bga(board, "U2", right_x, cy, "left", nets)
    pic_pads = build_pic(board, cx, cy, nets)
    phases = build_vrm(board, nets)

    # The planes were poured when the board had no pads, so every zone filled
    # as isolated copper. Re-pouring now that U1, U2 and the DrMOS phases
    # exist is what actually connects GND and VDD to silicon. A pour is only
    # valid for the pad set it was filled against.
    pcbnew.ZONE_FILLER(board).Fill(board.Zones())

    pcbnew.SaveBoard(path, board)

    total_pads = sum(len(list(f.Pads())) for f in board.GetFootprints())
    print("components   : %d" % len(list(board.GetFootprints())))
    print("  BGA-2500   : 2  (U1, U2)")
    print("  TFLN PIC   : 1  (PIC1), %d electrical pads" % pic_pads)
    print("  DrMOS      : %d phases" % phases)
    print("pads total   : %d" % total_pads)
    print("nets         : %d" % len(nets))
    print()
    print("U1 ball map  : vdd=%d gnd=%d signal=%d optical=%d"
          % (t1["vdd"], t1["gnd"], t1["signal"], t1["optical"]))
    print("U2 ball map  : vdd=%d gnd=%d signal=%d optical=%d"
          % (t2["vdd"], t2["gnd"], t2["signal"], t2["optical"]))
    print()
    print("optical lanes: %d per die per direction (16 WDM channels)"
          % WDM_LANES)
    print("              target 200 Gbps/lane = 3.2T; framing layer today")
    print("              drives 33.3 Mbps/lane -- see BANDWIDTH-STATEMENT.md")
    print("              differential, so %d balls per die"
          % (WDM_LANES * 2 * 2))
    print()
    print("PROVISIONAL. The ball map is generated by rule, not read from a")
    print("vendor file. It is structurally realistic so that placement and")
    print("routing are meaningful, and it is not a released pinout.")
    return 0


if __name__ == "__main__":
    sys.exit(main())
